insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-money-trivia',
  'Money Trivia: Banknotes, Coins and Everyday Concepts',
  'Eight questions about the money in your pocket: fiat currency, legal tender, numismatics, mints and the stories behind bills and coins.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'lifestyle'),
  '[{"id":"q1","question":"What is fiat money?","options":[{"id":"a","text":"Money backed by gold reserves","is_correct":false},{"id":"b","text":"Money that has value by government decree","is_correct":true},{"id":"c","text":"Money issued only in coins","is_correct":false},{"id":"d","text":"Money that always keeps its value","is_correct":false}],"explanation":"Fiat comes from Latin for ''let it be done'': most modern currencies, like the dollar and the euro, are fiat money."},{"id":"q2","question":"Whose portrait appears on the United States one-dollar bill?","options":[{"id":"a","text":"Abraham Lincoln","is_correct":false},{"id":"b","text":"Benjamin Franklin","is_correct":false},{"id":"c","text":"George Washington","is_correct":true},{"id":"d","text":"Thomas Jefferson","is_correct":false}],"explanation":"Washington has been on the one-dollar bill since 1869; Lincoln is on the five and Franklin on the hundred."},{"id":"q3","question":"What does the word ''numismatics'' refer to?","options":[{"id":"a","text":"The study of numbers in banking","is_correct":false},{"id":"b","text":"The study and collection of coins and currency","is_correct":true},{"id":"c","text":"The design of credit cards","is_correct":false},{"id":"d","text":"The math behind interest","is_correct":false}],"explanation":"Numismatics covers coins, tokens and paper money, and serious collectors trace history through them."},{"id":"q4","question":"Which commodity is traditionally linked to the origin of the word ''salary''?","options":[{"id":"a","text":"Salt","is_correct":true},{"id":"b","text":"Gold","is_correct":false},{"id":"c","text":"Pepper","is_correct":false},{"id":"d","text":"Wheat","is_correct":false}],"explanation":"''Salary'' comes from the Latin salarium, an allowance linked to salt, which was precious in the ancient world."},{"id":"q5","question":"What is the main job of a mint?","options":[{"id":"a","text":"Printing paper banknotes","is_correct":false},{"id":"b","text":"Storing gold bars","is_correct":false},{"id":"c","text":"Manufacturing coins","is_correct":true},{"id":"d","text":"Setting interest rates","is_correct":false}],"explanation":"A mint strikes coins for the state; banknotes usually come from separate printing works."},{"id":"q6","question":"What does it mean that a currency is ''legal tender''?","options":[{"id":"a","text":"It must be accepted to settle debts","is_correct":true},{"id":"b","text":"It never loses value","is_correct":false},{"id":"c","text":"It is backed by silver","is_correct":false},{"id":"d","text":"It can be used anywhere in the world","is_correct":false}],"explanation":"Legal tender is the money a creditor cannot refuse for settling a debt within its jurisdiction."},{"id":"q7","question":"Which country put the first polymer (plastic) banknotes into general circulation?","options":[{"id":"a","text":"Canada","is_correct":false},{"id":"b","text":"The United Kingdom","is_correct":false},{"id":"c","text":"Japan","is_correct":false},{"id":"d","text":"Australia","is_correct":true}],"explanation":"Australia issued a polymer ten-dollar note for its 1988 bicentenary and later converted all its notes."},{"id":"q8","question":"What do the letters ATM stand for?","options":[{"id":"a","text":"Automated teller machine","is_correct":true},{"id":"b","text":"Automatic transfer module","is_correct":false},{"id":"c","text":"Advanced treasury machine","is_correct":false},{"id":"d","text":"Account tracking monitor","is_correct":false}],"explanation":"The first ATM was installed by Barclays in London in 1967 and paid out cash against special vouchers."}]'::jsonb,
  null,
  array['money', 'trivia', 'currency', 'personal finance']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-dinero',
  'Trivia de dinero: billetes, monedas y conceptos clave',
  'Ocho preguntas sobre el dinero de cada día: dinero fíat, curso legal, numismática, casas de moneda y las historias detrás de billetes y monedas.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'lifestyle'),
  '[{"id":"q1","question":"¿Qué es el dinero fíat?","options":[{"id":"a","text":"Dinero respaldado por reservas de oro","is_correct":false},{"id":"b","text":"Dinero que tiene valor por decreto del gobierno","is_correct":true},{"id":"c","text":"Dinero emitido solo en monedas","is_correct":false},{"id":"d","text":"Dinero que conserva siempre su valor","is_correct":false}],"explanation":"Fíat viene del latín ''hágase'': la mayoría de las monedas modernas, como el dólar y el euro, son dinero fíat."},{"id":"q2","question":"¿De quién es el retrato del billete de un dólar de Estados Unidos?","options":[{"id":"a","text":"Abraham Lincoln","is_correct":false},{"id":"b","text":"Benjamin Franklin","is_correct":false},{"id":"c","text":"George Washington","is_correct":true},{"id":"d","text":"Thomas Jefferson","is_correct":false}],"explanation":"Washington está en el billete de un dólar desde 1869; Lincoln aparece en el de cinco y Franklin en el de cien."},{"id":"q3","question":"¿A qué se refiere la palabra ''numismática''?","options":[{"id":"a","text":"Al estudio de los números en la banca","is_correct":false},{"id":"b","text":"Al estudio y colección de monedas y billetes","is_correct":true},{"id":"c","text":"Al diseño de tarjetas de crédito","is_correct":false},{"id":"d","text":"A las matemáticas del interés","is_correct":false}],"explanation":"La numismática abarca monedas, fichas y papel moneda, y permite reconstruir la historia a través de ellos."},{"id":"q4","question":"¿Con qué producto se vincula tradicionalmente el origen de la palabra ''salario''?","options":[{"id":"a","text":"La sal","is_correct":true},{"id":"b","text":"El oro","is_correct":false},{"id":"c","text":"La pimienta","is_correct":false},{"id":"d","text":"El trigo","is_correct":false}],"explanation":"''Salario'' viene del latín salarium, una asignación vinculada a la sal, un bien muy valioso en la antigüedad."},{"id":"q5","question":"¿Cuál es la función principal de una casa de moneda?","options":[{"id":"a","text":"Imprimir billetes de papel","is_correct":false},{"id":"b","text":"Guardar lingotes de oro","is_correct":false},{"id":"c","text":"Fabricar monedas","is_correct":true},{"id":"d","text":"Fijar los tipos de interés","is_correct":false}],"explanation":"La casa de moneda acuña monedas para el Estado; los billetes suelen imprimirse en fábricas aparte."},{"id":"q6","question":"¿Qué significa que una moneda tenga ''curso legal''?","options":[{"id":"a","text":"Que debe aceptarse para saldar deudas","is_correct":true},{"id":"b","text":"Que nunca pierde valor","is_correct":false},{"id":"c","text":"Que está respaldada por plata","is_correct":false},{"id":"d","text":"Que se puede usar en todo el mundo","is_correct":false}],"explanation":"El curso legal obliga al acreedor a aceptar esa moneda para saldar una deuda dentro de su jurisdicción."},{"id":"q7","question":"¿Qué país puso en circulación los primeros billetes de polímero (plástico)?","options":[{"id":"a","text":"Canadá","is_correct":false},{"id":"b","text":"El Reino Unido","is_correct":false},{"id":"c","text":"Japón","is_correct":false},{"id":"d","text":"Australia","is_correct":true}],"explanation":"Australia emitió un billete de diez dólares de polímero por su bicentenario en 1988 y luego renovó toda su serie."},{"id":"q8","question":"¿Qué significan las siglas ATM?","options":[{"id":"a","text":"Automated teller machine (cajero automático)","is_correct":true},{"id":"b","text":"Automatic transfer module","is_correct":false},{"id":"c","text":"Advanced treasury machine","is_correct":false},{"id":"d","text":"Account tracking monitor","is_correct":false}],"explanation":"El primer cajero automático lo instaló Barclays en Londres en 1967 y entregaba efectivo con vales especiales."}]'::jsonb,
  null,
  array['dinero', 'trivia', 'monedas', 'finanzas']::text[],
  3,
  'published',
  false,
  false,
  now()
)
